/* ---- downloadable user manual (PDF embedded) ---- */
const MANUAL_B64="";
function manualDl(){try{const bin=atob(MANUAL_B64),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);const bl=new Blob([u],{type:"application/pdf"}),a=document.createElement("a");a.href=URL.createObjectURL(bl);a.download="Fenestra_User_Manual.pdf";document.body.appendChild(a);a.click();setTimeout(()=>{a.remove();URL.revokeObjectURL(a.href)},800)}catch(x){alert("The manual could not be prepared: "+x.message)}}
const _nav18=navHtml;navHtml=function(){return _nav18()+`<div class="ng">Help</div><button onclick="manualDl()"><span class="ni">📘</span>User manual (PDF)</button>`};
